def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Find the 3-cell horizontal color sequence.
    motif=None
    for r in range(h):
        for c in range(w-2):
            if all(grid[r][c+i] != 0 for i in range(3)):
                motif=(r,c,[grid[r][c+i] for i in range(3)]); break
        if motif: break
    if not motif: return out
    r,c,colors=motif
    # Each motif cell extends as an infinite ray along its column; external matching
    # markers additionally draw a horizontal ray from their row to that column.
    for i,color in enumerate(colors):
        col=c+i
        for rr in range(h):
            if out[rr][col]==0: out[rr][col]=color
        for rr in range(h):
            for cc in range(w):
                if grid[rr][cc]==color and (rr,cc)!=(r,col):
                    lo,hi=sorted((cc,col))
                    for x in range(lo,hi+1): out[rr][x]=color
    return out
